const urls = [
  "https://www.moroccoworldnews.com/2025/09/259353/moroccos-35-15-billion-green-hydrogen-gamble-ambitious-plans-amid-market-doubts/",
  // Add more URLs as needed
];

return urls.map(url => ({
  json: {
    article_url: url,
    extraction_id: Math.random().toString(36).substring(7),
    timestamp: new Date().toISOString()
  }
}));

// Process Tavily extraction response
const response = $input.first().json;
const originalData = $input.first().json;

let extractedContent = {
  article_url: originalData.article_url,
  extraction_id: originalData.extraction_id,
  title: '',
  content: '',
  author: '',
  published_date: '',
  summary: '',
  raw_content_length: 0
};

try {
  if (response.results && response.results[0]) {
    const result = response.results[0];

    extractedContent.title = result.title || '';
    extractedContent.content = result.text || result.content || '';
    extractedContent.author = result.author || '';
    extractedContent.published_date = result.published_date || '';
    extractedContent.summary = result.summary || response.answer || '';
    extractedContent.raw_content_length = extractedContent.content.length;

    // Add metadata if available
    if (result.metadata) {
      extractedContent.metadata = result.metadata;
    }
  }
} catch (error) {
  console.error('Error processing Tavily response:', error);
  extractedContent.error = error.message;
}

// Ensure content is not too long for OpenAI
const maxLength = 30000; // GPT-4 can handle more
if (extractedContent.content.length > maxLength) {
  extractedContent.content = extractedContent.content.substring(0, maxLength) + '...';
  extractedContent.truncated = true;
}

return extractedContent;

